const SITE_NAMES={
  all:"All Locations",
  indiana:"Indiana",
  la26:"LA 26th St.",
  maywood:"LA Maywood",
  newyork:"New York",
  sacramento:"Sacramento"
};

let currentSite=
  localStorage.getItem("lamonicasCurrentSite") || "all";

const ASSETS=SHARED_ASSET_MASTER;


const DB_NAME="LamonicasOperationsHub";
const STORE="files";
let db;
let mainDbOpenPromise=null;

function openDB(){
  if(db)return Promise.resolve();
  if(mainDbOpenPromise)return mainDbOpenPromise;

  mainDbOpenPromise=new Promise((resolve,reject)=>{
    const request=indexedDB.open(DB_NAME);

    request.onupgradeneeded=e=>{
      const database=e.target.result;
      if(!database.objectStoreNames.contains(STORE)){
        database.createObjectStore(STORE,{keyPath:"id",autoIncrement:true});
      }
      if(!database.objectStoreNames.contains("workOrders")){
        database.createObjectStore("workOrders",{keyPath:"id"});
      }
      if(!database.objectStoreNames.contains("production")){
        database.createObjectStore("production",{keyPath:"key"});
      }
      if(!database.objectStoreNames.contains("importHistory")){
        database.createObjectStore("importHistory",{keyPath:"id",autoIncrement:true});
      }
      if(!database.objectStoreNames.contains("siteSummaries")){
        database.createObjectStore("siteSummaries",{keyPath:"site"});
      }
    };

    request.onsuccess=e=>{
      db=e.target.result;
      db.onversionchange=()=>{
        db.close();
        db=null;
        mainDbOpenPromise=null;
      };
      resolve();
    };

    request.onerror=()=>reject(request.error||new Error("Could not open dashboard database."));
    request.onblocked=()=>reject(new Error("Dashboard data is locked by another browser tab. Close older Ops Hub tabs and try again."));
  }).finally(()=>{
    if(!db)mainDbOpenPromise=null;
  });

  return mainDbOpenPromise;
}

function addFile(file,category){
  return new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,"readwrite");

    const record={
      name:file.name,
      type:file.type,
      size:file.size,
      category,
      site:currentSite==="all" ? "all" : currentSite,
      date:new Date().toISOString(),
      blob:file
    };

    const req=tx.objectStore(STORE).add(record);

    req.onsuccess=()=>resolve();
    req.onerror=()=>reject(req.error);
  });
}
function storeConfirmedSourceFile(file,metadata={}){
  if(!file)return Promise.resolve(null);
  return new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,"readwrite");
    const record={
      name:file.name,
      type:file.type,
      size:file.size,
      category:"dataupload-source",
      site:metadata.site||currentSite||"all",
      date:metadata.importedAt||new Date().toISOString(),
      reportType:metadata.reportType||"",
      importArea:metadata.area||"",
      blob:file
    };
    const req=tx.objectStore(STORE).add(record);
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}

function getFiles(category){
  return new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,"readonly");
    const req=tx.objectStore(STORE).getAll();

    req.onsuccess=()=>{
      resolve(
        req.result
        .filter(x=>
          x.category===category &&
          (
            currentSite==="all" ||
            x.site===currentSite ||
            x.site==="all" ||
            !x.site
          )
        )
        .sort((a,b)=>new Date(b.date)-new Date(a.date))
      );
    };

    req.onerror=()=>reject(req.error);
  });
}

function getFile(id){
  return new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,"readonly");
    const req=tx.objectStore(STORE).get(id);
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}

function deleteFileFromDB(id){
  return new Promise((resolve,reject)=>{
    const tx=db.transaction(STORE,"readwrite");
    const req=tx.objectStore(STORE).delete(id);
    req.onsuccess=()=>resolve();
    req.onerror=()=>reject(req.error);
  });
}

function showPage(page){
  document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));
  document.querySelectorAll(".nav-btn").forEach(x=>x.classList.remove("active"));

  document.getElementById(page).classList.add("active");

  const nav=document.querySelector(`.nav-btn[data-page="${page}"]`);
  if(nav) nav.classList.add("active");

  window.scrollTo({top:0,behavior:"smooth"});
}

document.querySelectorAll(".nav-btn").forEach(button=>{
  button.addEventListener("click",()=>showPage(button.dataset.page));
});


function updateSiteLabels(){
  document.querySelectorAll(".global-site-label").forEach(el=>{
    el.textContent=`📍 ${SITE_NAMES[currentSite]}`;
  });
  document.getElementById("siteSelector").value=currentSite;
}

async function handleFiles(files,category,page){
  if(!files || !files.length)return;

  for(const file of files){
    await addFile(file,category);
  }

  await renderFiles(category);

  if(page) showPage(page);

  toast(files.length===1 ? `${files[0].name} added` : `${files.length} files added`);
}

document.querySelectorAll(".drop-target").forEach(target=>{
  target.addEventListener("dragover",e=>{
    e.preventDefault();
    e.stopPropagation();
    target.classList.add("dragging-over");
  });

  target.addEventListener("dragleave",()=>{
    target.classList.remove("dragging-over");
  });

  target.addEventListener("drop",async e=>{
    e.preventDefault();
    e.stopPropagation();

    target.classList.remove("dragging-over");

    const files=[...e.dataTransfer.files];
    const category=target.dataset.category;
    const page=target.dataset.page || category;

    if(files.length){
      await handleFiles(files,category,page);
    }
  });
});

document.querySelectorAll(".nav-btn").forEach(tab=>{
  tab.addEventListener("dragover",e=>{
    e.preventDefault();
    tab.classList.add("dragging-over");
  });

  tab.addEventListener("dragleave",()=>{
    tab.classList.remove("dragging-over");
  });

  tab.addEventListener("drop",async e=>{
    e.preventDefault();
    tab.classList.remove("dragging-over");

    const files=[...e.dataTransfer.files];
    if(!files.length)return;

    const category=tab.dataset.category;
    const page=tab.dataset.page;

    if(category==="home"){
      toast("Drop the file onto the section where it belongs.");
      return;
    }

    await handleFiles(files,category,page);
  });
});

document.querySelectorAll(".uploader").forEach(uploader=>{
  const category=uploader.dataset.category;
  const input=uploader.querySelector(".file-input");
  const button=uploader.querySelector(".upload-btn");

  button.addEventListener("click",e=>{
    e.preventDefault();
    e.stopPropagation();
    input.click();
  });

  uploader.addEventListener("click",e=>{
    if(e.target!==button) input.click();
  });

  input.addEventListener("change",async ()=>{
    await handleFiles([...input.files],category,null);
    input.value="";
  });

  uploader.addEventListener("dragover",e=>{
    e.preventDefault();
    uploader.classList.add("dragging-over");
  });

  uploader.addEventListener("dragleave",()=>{
    uploader.classList.remove("dragging-over");
  });

  uploader.addEventListener("drop",async e=>{
    e.preventDefault();
    e.stopPropagation();

    uploader.classList.remove("dragging-over");

    await handleFiles([...e.dataTransfer.files],category,null);
  });
});

async function renderFiles(category){
  const container=document.getElementById(`${category}-list`);
  if(!container)return;

  const files=await getFiles(category);

  if(!files.length){
    container.innerHTML=`<div class="empty">No files uploaded for ${SITE_NAMES[currentSite]}.</div>`;
    return;
  }

  container.innerHTML=files.map(file=>`
    <div class="file-card">
      <div class="file-icon">${fileIcon(file.name)}</div>

      <div class="file-details">
        <div class="file-name">${escapeHTML(file.name)}</div>
        <div class="file-meta">
          ${fileSize(file.size)}
          •
          ${SITE_NAMES[file.site] || "All Locations"}
          •
          ${new Date(file.date).toLocaleDateString()}
        </div>
      </div>

      <div class="file-actions">
        <button class="file-button" onclick="openStoredFile(${file.id})">Open</button>
        <button class="file-button" onclick="downloadStoredFile(${file.id})">↓</button>
        <button class="file-button delete" onclick="removeStoredFile(${file.id},'${category}')">Delete</button>
      </div>
    </div>
  `).join("");
}

async function renderAllFiles(){
  for(const category of ["kpi","manuals","purchasing","safety","employees"]){
    await renderFiles(category);
  }
}

async function openStoredFile(id){
  const file=await getFile(id);
  if(!file)return;

  const url=URL.createObjectURL(file.blob);
  window.open(url,"_blank");

  setTimeout(()=>URL.revokeObjectURL(url),60000);
}

async function downloadStoredFile(id){
  const file=await getFile(id);
  if(!file)return;

  const url=URL.createObjectURL(file.blob);
  const link=document.createElement("a");

  link.href=url;
  link.download=file.name;

  document.body.appendChild(link);
  link.click();
  link.remove();

  URL.revokeObjectURL(url);
}

async function removeStoredFile(id,category){
  if(!confirm("Delete this file from the Operations Hub?")) return;

  await deleteFileFromDB(id);
  await renderFiles(category);

  toast("File deleted");
}

function renderAssets(){
  const search=document.getElementById("assetSearch").value.toLowerCase().trim();
  const location=document.getElementById("assetLocationFilter").value;

  const filtered=ASSETS.filter(asset=>{
    const text=`
      ${asset.name}
      ${asset.manufacturer}
      ${asset.location}
      ${asset.area}
      ${asset.parts.join(" ")}
    `.toLowerCase();

    const matchesSite=
      currentSite==="all" ||
      asset.site===currentSite;

    const matchesSearch=
      !search ||
      text.includes(search);

    const matchesLocation=
      !location ||
      asset.location===location;

    return matchesSite && matchesSearch && matchesLocation;
  });

  document.getElementById("assetCount").textContent=filtered.length;

  const grid=document.getElementById("assetGrid");

  if(!filtered.length){
    grid.innerHTML=`<div class="empty">No assets for this location yet.</div>`;
    return;
  }

  grid.innerHTML=filtered.map((asset,index)=>`
    <div class="asset-card" onclick="openAsset(${ASSETS.indexOf(asset)})">
      <h4>${escapeHTML(asset.name)}</h4>

      <div class="asset-meta">
        <span class="online">● ${escapeHTML(asset.status)}</span>
        <br>
        ${SITE_NAMES[asset.site]}
        <br>
        ${asset.manufacturer ? escapeHTML(asset.manufacturer)+"<br>" : ""}
        ${escapeHTML(asset.location || "Location not listed")}
        ${asset.area ? " • "+escapeHTML(asset.area) : ""}
        <br>
        ${asset.parts.length} known part${asset.parts.length===1 ? "" : "s"}
      </div>
    </div>
  `).join("");
}

async function openAsset(index){
  const asset=ASSETS[index];
  const detail=document.getElementById("assetDetail");

  const category=
    "asset-"+asset.site+"-"+asset.name
    .toLowerCase()
    .replace(/[^a-z0-9]+/g,"-")
    .replace(/^-|-$/g,"");

  const files=await getFiles(category);

  detail.classList.add("active");

  detail.innerHTML=`
    <div class="section-title">
      <h3>${escapeHTML(asset.name)}</h3>
      <span>${SITE_NAMES[asset.site]}</span>
    </div>

    <div class="asset-detail-grid">

      <div class="panel">
        <h3>Asset Information</h3>

        <div class="detail-list">
          <strong>Asset:</strong> ${escapeHTML(asset.name)}<br>
          <strong>Site:</strong> ${SITE_NAMES[asset.site]}<br>
          <strong>Manufacturer:</strong> ${escapeHTML(asset.manufacturer || "Not listed")}<br>
          <strong>Location:</strong> ${escapeHTML(asset.location || "Not listed")}<br>
          <strong>Area:</strong> ${escapeHTML(asset.area || "Not listed")}<br>
          <strong>Status:</strong> <span class="online">${escapeHTML(asset.status)}</span>
        </div>

        <div class="parts-list">
          <strong>Known Spare Parts</strong>

          ${
            asset.parts.length
            ? `<ul>${asset.parts.map(p=>`<li>${escapeHTML(p)}</li>`).join("")}</ul>`
            : `<div style="margin-top:8px;color:var(--muted);font-size:12px">No spare parts entered yet.</div>`
          }
        </div>
      </div>

      <div class="panel">
        <div class="uploader asset-uploader" data-asset-category="${category}">
          <div class="upload-icon">📎</div>
          <h3>Drop files for ${escapeHTML(asset.name)}</h3>
          <p>Manuals, spare-parts lists, electrical drawings, mechanical drawings or photos.</p>
          <button class="upload-btn" onclick="event.stopPropagation();document.getElementById('${category}-input').click()">Choose Files</button>
          <input id="${category}-input" class="file-input" type="file" multiple onchange="uploadAssetFiles(this,'${category}')">
        </div>

        <div class="file-list" id="${category}-list">
          ${
            files.length
            ? files.map(file=>assetFileHTML(file,category)).join("")
            : `<div class="empty">No asset-specific files yet.</div>`
          }
        </div>
      </div>

    </div>
  `;

  const uploader=detail.querySelector(".asset-uploader");

  uploader.addEventListener("dragover",e=>{
    e.preventDefault();
    uploader.classList.add("dragging-over");
  });

  uploader.addEventListener("dragleave",()=>{
    uploader.classList.remove("dragging-over");
  });

  uploader.addEventListener("drop",async e=>{
    e.preventDefault();
    e.stopPropagation();

    uploader.classList.remove("dragging-over");

    await uploadAssetFileList([...e.dataTransfer.files],category);
  });

  detail.scrollIntoView({behavior:"smooth",block:"start"});
}

function assetFileHTML(file,category){
  return `
    <div class="file-card">
      <div class="file-icon">${fileIcon(file.name)}</div>

      <div class="file-details">
        <div class="file-name">${escapeHTML(file.name)}</div>
        <div class="file-meta">${fileSize(file.size)}</div>
      </div>

      <div class="file-actions">
        <button class="file-button" onclick="openStoredFile(${file.id})">Open</button>
        <button class="file-button delete" onclick="deleteAssetFile(${file.id},'${category}')">Delete</button>
      </div>
    </div>
  `;
}

async function uploadAssetFiles(input,category){
  await uploadAssetFileList([...input.files],category);
  input.value="";
}

async function uploadAssetFileList(files,category){
  if(!files.length)return;

  for(const file of files){
    await addFile(file,category);
  }

  await refreshAssetFileList(category);

  toast("Asset files added");
}

async function refreshAssetFileList(category){
  const container=document.getElementById(`${category}-list`);
  if(!container)return;

  const files=await getFiles(category);

  container.innerHTML=
    files.length
    ? files.map(file=>assetFileHTML(file,category)).join("")
    : `<div class="empty">No asset-specific files yet.</div>`;
}

async function deleteAssetFile(id,category){
  if(!confirm("Delete this asset file?"))return;

  await deleteFileFromDB(id);
  await refreshAssetFileList(category);

  toast("Asset file deleted");
}

const PURCHASING_EMAIL_KEY="lamonicasPurchasingEmail";
const RECEIVING_KEY="lamonicasReceivingQueue";
let purchaseFilter="All";

function loadPurchasingEmail(){
  document.getElementById("purchasingEmail").value=
    localStorage.getItem(PURCHASING_EMAIL_KEY) || "";
}

function savePurchasingEmail(){
  const email=document.getElementById("purchasingEmail").value.trim();

  if(!email){
    alert("Enter the Purchasing department email first.");
    return;
  }

  localStorage.setItem(PURCHASING_EMAIL_KEY,email);

  toast("Purchasing email saved");
}

function emailPurchasing(order){
  const email=localStorage.getItem(PURCHASING_EMAIL_KEY);

  if(!email){
    toast("Order saved. Add the Purchasing email to enable email notifications.");
    return;
  }

  const subject=`Received Order - ${order.poNumber} - ${order.vendor}`;

  const amount=
    order.invoiceAmount
    ? "$"+Number(order.invoiceAmount).toFixed(2)
    : "Not entered";

  const body=`A received order has been added to the Lamonica's Operations Hub.

Site: ${SITE_NAMES[order.site]}
PO Number: ${order.poNumber}
Vendor: ${order.vendor}

Order / Item:
${order.description}

Received Date: ${order.receivedDate || "Not entered"}
Received By: ${order.receivedBy || "Not entered"}

Invoice Number: ${order.invoiceNumber || "Not received"}
Invoice Amount: ${amount}

Status: ${order.status}

Notes:
${order.notes || "None"}

Please review this order in the Purchasing & Invoices area.

Lamonica's Operations Hub
Designed by Lamonica's Engineering Team`;

  const mailto=
    `mailto:${encodeURIComponent(email)}`+
    `?subject=${encodeURIComponent(subject)}`+
    `&body=${encodeURIComponent(body)}`;

  window.location.href=mailto;
}

function getReceivingOrders(){
  return JSON.parse(localStorage.getItem(RECEIVING_KEY) || "[]");
}

function saveReceivingOrders(orders){
  localStorage.setItem(RECEIVING_KEY,JSON.stringify(orders));
}

document.getElementById("receivingForm").addEventListener("submit",e=>{
  e.preventDefault();

  if(currentSite==="all"){
    alert("Select a specific site before adding a received order.");
    return;
  }

  const orders=getReceivingOrders();

  const order={
    id:Date.now(),
    site:currentSite,
    poNumber:document.getElementById("poNumber").value.trim(),
    vendor:document.getElementById("vendor").value.trim(),
    description:document.getElementById("orderDescription").value.trim(),
    receivedDate:document.getElementById("receivedDate").value,
    receivedBy:document.getElementById("receivedBy").value.trim(),
    invoiceNumber:document.getElementById("invoiceNumber").value.trim(),
    invoiceAmount:document.getElementById("invoiceAmount").value,
    status:document.getElementById("orderStatus").value,
    notes:document.getElementById("orderNotes").value.trim(),
    created:new Date().toISOString()
  };

  orders.unshift(order);

  saveReceivingOrders(orders);

  document.getElementById("receivingForm").reset();

  setToday();
  renderPurchasing();

  toast("Received order added");

  emailPurchasing(order);
});

function changeOrderStatus(id,status){
  const orders=getReceivingOrders();
  const order=orders.find(x=>x.id===id);

  if(!order)return;

  order.status=status;

  saveReceivingOrders(orders);
  renderPurchasing();

  toast(`Order moved to ${status}`);
}

function deleteReceivingOrder(id){
  if(!confirm("Delete this receiving record?"))return;

  let orders=getReceivingOrders();
  orders=orders.filter(x=>x.id!==id);

  saveReceivingOrders(orders);
  renderPurchasing();

  toast("Receiving record deleted");
}

function setPurchaseFilter(filter,button){
  purchaseFilter=filter;

  document.querySelectorAll(".filter-btn")
    .forEach(btn=>btn.classList.remove("active"));

  button.classList.add("active");

  renderReceivingQueue();
}

function openPurchaseFilter(filter){
  showPage("purchasing");

  purchaseFilter=filter;

  document.querySelectorAll(".filter-btn").forEach(btn=>{
    btn.classList.toggle("active",btn.textContent.trim()===filter);
  });

  renderReceivingQueue();
}

function siteFilteredOrders(){
  const orders=getReceivingOrders();

  return orders.filter(order=>
    currentSite==="all" ||
    order.site===currentSite
  );
}

function renderPurchasing(){
  const orders=siteFilteredOrders();

  const received=orders.filter(x=>x.status==="Received").length;
  const waiting=orders.filter(x=>x.status==="Waiting for Invoice").length;
  const ready=orders.filter(x=>x.status==="Ready to Pay").length;
  const hold=orders.filter(x=>x.status==="On Hold").length;
  const paid=orders.filter(x=>x.status==="Paid").length;

  document.getElementById("receivedCount").textContent=received;
  document.getElementById("waitingInvoiceCount").textContent=waiting;
  document.getElementById("readyToPayCount").textContent=ready;
  document.getElementById("holdCount").textContent=hold;
  document.getElementById("paidCount").textContent=paid;

  document.getElementById("homeReceived").textContent=received;
  document.getElementById("homeWaitingInvoice").textContent=waiting;
  document.getElementById("homeReadyToPay").textContent=ready;
  document.getElementById("homeOnHold").textContent=hold;

  renderReceivingQueue();
}

function renderReceivingQueue(){
  let orders=siteFilteredOrders();

  const search=document.getElementById("purchaseSearch").value.toLowerCase().trim();

  if(purchaseFilter!=="All"){
    orders=orders.filter(x=>x.status===purchaseFilter);
  }

  if(search){
    orders=orders.filter(order=>{
      const text=`
        ${SITE_NAMES[order.site]}
        ${order.poNumber}
        ${order.vendor}
        ${order.description}
        ${order.invoiceNumber}
        ${order.receivedBy}
        ${order.notes}
      `.toLowerCase();

      return text.includes(search);
    });
  }

  const queue=document.getElementById("receivingQueue");

  if(!orders.length){
    queue.innerHTML=`<div class="empty">No matching orders.</div>`;
    return;
  }

  queue.innerHTML=orders.map(order=>{
    const statusClass=order.status.toLowerCase().replaceAll(" ","-");

    const amount=
      order.invoiceAmount
      ? `$${Number(order.invoiceAmount).toLocaleString(undefined,{
          minimumFractionDigits:2,
          maximumFractionDigits:2
        })}`
      : "—";

    return `
      <div class="order-card">

        <div class="order-top">
          <div>
            <div class="order-title">
              ${escapeHTML(order.poNumber)} • ${escapeHTML(order.vendor)}
            </div>

            <div class="order-meta">
              ${SITE_NAMES[order.site] || "Site not set"}
              •
              Received:
              ${escapeHTML(order.receivedDate || "Not entered")}
              ${order.receivedBy ? ` • By ${escapeHTML(order.receivedBy)}` : ""}
            </div>
          </div>

          <span class="status-badge status-${statusClass}">
            ${escapeHTML(order.status)}
          </span>
        </div>

        <div class="order-detail">
          <strong>Order:</strong> ${escapeHTML(order.description)}
          <br>
          <strong>Invoice:</strong> ${escapeHTML(order.invoiceNumber || "Not received")}
          <br>
          <strong>Amount:</strong> ${amount}
          ${order.notes ? `<br><strong>Notes:</strong> ${escapeHTML(order.notes)}` : ""}
        </div>

        <div class="order-actions">
          <button class="small-btn" onclick="changeOrderStatus(${order.id},'Received')">Received</button>
          <button class="small-btn" onclick="changeOrderStatus(${order.id},'Waiting for Invoice')">Waiting for Invoice</button>
          <button class="small-btn" onclick="changeOrderStatus(${order.id},'Ready to Pay')">Ready to Pay</button>
          <button class="small-btn" onclick="changeOrderStatus(${order.id},'On Hold')">On Hold</button>
          <button class="small-btn" onclick="changeOrderStatus(${order.id},'Paid')">Paid</button>
          <button class="small-btn delete" onclick="deleteReceivingOrder(${order.id})">Delete</button>
        </div>

      </div>
    `;
  }).join("");
}

function setToday(){
  const input=document.getElementById("receivedDate");

  if(input.value)return;

  const today=new Date();

  const local=
    new Date(
      today.getTime()-
      today.getTimezoneOffset()*60000
    )
    .toISOString()
    .split("T")[0];

  input.value=local;
}

function fileIcon(name){
  const ext=name.split(".").pop().toLowerCase();

  if(ext==="pdf")return "📕";
  if(["xlsx","xls","csv"].includes(ext))return "📊";
  if(["doc","docx"].includes(ext))return "📘";
  if(["png","jpg","jpeg","gif","webp"].includes(ext))return "🖼️";
  if(["dwg","dxf"].includes(ext))return "📐";

  return "📄";
}

function fileSize(bytes){
  if(bytes<1024)return bytes+" B";
  if(bytes<1048576)return (bytes/1024).toFixed(1)+" KB";
  return (bytes/1048576).toFixed(1)+" MB";
}

function escapeHTML(text){
  const div=document.createElement("div");
  div.textContent=text;
  return div.innerHTML;
}

function toast(message){
  const el=document.getElementById("toast");

  el.textContent=message;
  el.classList.add("show");

  clearTimeout(window.toastTimeout);

  window.toastTimeout=setTimeout(()=>{
    el.classList.remove("show");
  },2200);
}


const HUB_SETTINGS_KEY="lamonicasHubSettings";
