(function(){
const PV_EMAIL="vlara@lamonicaspizza.com";
const PV_KEY="lamonicas_purchasing_vendor_files_v1";
const PV_VENDORS=[
 ["san-cassiano","San Cassiano"],
 ["matrix","Matrix"],
 ["brenton","Brenton"],
 ["grainger","Grainger"],
 ["kb-gemini","KB / Gemini"],
 ["motion-industries","Motion Industries"],
 ["nvp","NVP"],
 ["amf","AMF"],
 ["other-parts","Other Parts Invoice"],
 ["technopool","Technopool"]
];
let pvActive="san-cassiano";
function pvSite(){return document.getElementById("siteSelector")?.value||"all"}
function pvRead(){try{return JSON.parse(localStorage.getItem(PV_KEY)||"{}")}catch(e){return {}}}
function pvWrite(x){localStorage.setItem(PV_KEY,JSON.stringify(x))}
function pvEsc(x){return String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function pvLabel(id){return PV_VENDORS.find(x=>x[0]===id)?.[1]||id}

function buildPurchasingVendorHub(){
 const page=document.getElementById("purchasing"); if(!page)return;
 let hub=document.getElementById("purchasingVendorHub");
 if(!hub){
   hub=document.createElement("div"); hub.id="purchasingVendorHub";
   const head=page.querySelector(".page-head")||page.firstElementChild;
   head.insertAdjacentElement("afterend",hub);
 }
 hub.innerHTML=`<div class="pv-tabs">${PV_VENDORS.map((v,i)=>`<button type="button" class="pv-tab ${v[0]===pvActive?"active":""}" data-pv="${v[0]}">${v[1]}</button>`).join("")}</div><div id="pvPanel"></div>`;
 hub.querySelectorAll(".pv-tab").forEach(b=>b.onclick=()=>{pvActive=b.dataset.pv;buildPurchasingVendorHub();});
 drawPurchasingVendorPanel();
}

function drawPurchasingVendorPanel(){
 const panel=document.getElementById("pvPanel");if(!panel)return;
 const label=pvLabel(pvActive), all=pvRead(), key=pvSite()+"::"+pvActive, files=all[key]||[];
 panel.innerHTML=`<div class="pv-panel">
   <div class="pv-panel-head"><div><h3>${pvEsc(label)}</h3><p>Invoices, purchase orders, quotes, packing slips and receiving documents.</p></div><div class="pv-email"><b>Send to:</b> ${PV_EMAIL}</div></div>
   <label class="pv-drop">📎 Add pictures or files for ${pvEsc(label)}<br><small>Photos, invoices, PDFs, quotes, packing slips and other documents</small><input id="pvInput" hidden type="file" multiple accept="image/*,.pdf,.doc,.docx,.xls,.xlsx,.csv,.txt"></label>
   <div class="pv-files">${files.map(f=>`<div class="pv-file"><b>${pvEsc(f.name)}</b><small>${pvEsc(f.date)}</small></div>`).join("")||'<div class="pv-file">No files uploaded yet.</div>'}</div>
   <div class="pv-attach-note">📎 ${files.length} file${files.length===1?"":"s"} selected/stored for this vendor. Your email app will open addressed to Vivian; attach the files shown above from your device.</div><div class="pv-actions"><button type="button" class="pv-email-btn" id="pvEmailBtn">Send Invoice to Vivian</button></div>
 </div>`;
 const input=document.getElementById("pvInput"),drop=panel.querySelector(".pv-drop");
 input.onchange=()=>pvAddFiles(input.files);
 drop.ondragover=e=>e.preventDefault();
 drop.ondrop=e=>{e.preventDefault();pvAddFiles(e.dataTransfer.files)};
 document.getElementById("pvEmailBtn").onclick=()=>{
   const subject=encodeURIComponent(label+" Invoice / Receiving Documentation");
   const body=encodeURIComponent("Hello Vivian,\n\nPlease see the "+label+" invoice / receiving documentation.\n\nThe order has been received and is ready for Purchasing review/payment.\n\nThank you.");
   location.href="mailto:"+PV_EMAIL+"?subject="+subject+"&body="+body;
 };
}
function pvAddFiles(files){
 const all=pvRead(),key=pvSite()+"::"+pvActive;all[key]=all[key]||[];
 [...files].forEach(f=>all[key].push({name:f.name,date:new Date().toLocaleString()}));
 pvWrite(all);drawPurchasingVendorPanel();
}
document.addEventListener("DOMContentLoaded",()=>{
 buildPurchasingVendorHub();
 document.querySelectorAll('.nav-btn[data-page="purchasing"]').forEach(b=>b.addEventListener("click",()=>setTimeout(buildPurchasingVendorHub,0)));
 document.getElementById("siteSelector")?.addEventListener("change",()=>setTimeout(drawPurchasingVendorPanel,0));
});
})();

