document.addEventListener("DOMContentLoaded", function(){
  const originalDraw = window.drawPurchasingVendorPanel;
  // Existing vendor UI uses its own scoped function, so observe the panel and add sorting controls after render.
  function addRecentSort(){
    const panel=document.getElementById("pvPanel");
    if(!panel || panel.querySelector(".pv-sort")) return;
    const files=panel.querySelector(".pv-files");
    if(!files) return;
    const wrap=document.createElement("div");
    wrap.className="pv-sort";
    wrap.innerHTML='<label>Sort files <select id="pvSortSelect"><option value="newest">Most Recent</option><option value="oldest">Oldest</option><option value="name">File Name</option></select></label>';
    files.parentNode.insertBefore(wrap,files);
    document.getElementById("pvSortSelect").onchange=sortVendorFiles;
    sortVendorFiles();
  }
  function sortVendorFiles(){
    const files=document.querySelector(".pv-files"); if(!files)return;
    const mode=document.getElementById("pvSortSelect")?.value||"newest";
    const cards=[...files.querySelectorAll(".pv-file")];
    cards.sort((a,b)=>{
      const at=a.querySelector("small")?.textContent||"", bt=b.querySelector("small")?.textContent||"";
      const an=a.querySelector("b")?.textContent||"", bn=b.querySelector("b")?.textContent||"";
      if(mode==="name") return an.localeCompare(bn);
      const ad=Date.parse(at)||0, bd=Date.parse(bt)||0;
      return mode==="oldest"?ad-bd:bd-ad;
    });
    cards.forEach(c=>files.appendChild(c));
  }
  const obs=new MutationObserver(()=>setTimeout(addRecentSort,0));
  const root=document.getElementById("purchasing");
  if(root) obs.observe(root,{childList:true,subtree:true});
  setTimeout(addRecentSort,50);
});

