"use strict";

const OPS_STORES={workOrders:"workOrders",production:"production",history:"importHistory",summaries:"siteSummaries"};
const OPS_FILTER_KEY="lamonicasOpsFilterV1";
let pendingOpsImport=null;

function opsTx(store,mode="readonly"){
  return db.transaction(store,mode).objectStore(store);
}
function opsGetAll(store){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store).getAll();
    req.onsuccess=()=>resolve(req.result||[]);
    req.onerror=()=>reject(req.error);
  });
}
function opsGet(store,key){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store).get(key);
    req.onsuccess=()=>resolve(req.result||null);
    req.onerror=()=>reject(req.error);
  });
}
function opsPut(store,value){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store,"readwrite").put(value);
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}
function opsAdd(store,value){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store,"readwrite").add(value);
    req.onsuccess=()=>resolve(req.result);
    req.onerror=()=>reject(req.error);
  });
}
function opsDelete(store,key){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store,"readwrite").delete(key);
    req.onsuccess=()=>resolve();
    req.onerror=()=>reject(req.error);
  });
}
function opsClear(store){
  return new Promise((resolve,reject)=>{
    const req=opsTx(store,"readwrite").clear();
    req.onsuccess=()=>resolve();
    req.onerror=()=>reject(req.error);
  });
}
function isOpsDataReset(){
  return localStorage.getItem("lamonicasOpsDataReset")==="1";
}
function setOpsDataReset(value){
  if(value)localStorage.setItem("lamonicasOpsDataReset","1");
  else localStorage.removeItem("lamonicasOpsDataReset");
}

function opsText(id,value){
  const el=document.getElementById(id);
  if(el)el.textContent=value==null||value===""?"—":String(value);
}
function opsMoney(value){
  return value==null?"—":new Intl.NumberFormat("en-US",{style:"currency",currency:"USD"}).format(value);
}
function opsHours(value){
  return value==null?"—":`${Number(value).toFixed(1)}h`;
}
function opsPercent(n,d){
  return d?`${Math.round(n/d*100)}%`:"—";
}
function opsDateString(value){
  if(value==null||value==="")return "";
  if(typeof value==="number" && window.XLSX?.SSF){
    const p=XLSX.SSF.parse_date_code(value);
    if(p)return `${p.y}-${String(p.m).padStart(2,"0")}-${String(p.d).padStart(2,"0")}`;
  }
  if(value instanceof Date && !isNaN(value)){
    return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,"0")}-${String(value.getDate()).padStart(2,"0")}`;
  }
  const text=String(value).trim();
  const iso=text.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if(iso)return `${iso[1]}-${iso[2].padStart(2,"0")}-${iso[3].padStart(2,"0")}`;
  const us=text.match(/^(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if(us){
    const y=us[3].length===2?`20${us[3]}`:us[3];
    return `${y}-${us[1].padStart(2,"0")}-${us[2].padStart(2,"0")}`;
  }
  const d=new Date(text);
  if(isNaN(d))return "";
  return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,"0")}-${String(d.getDate()).padStart(2,"0")}`;
}
function opsLocation(value){
  const s=String(value||"").trim().toLowerCase().replace(/[.\s_-]+/g," ");
  if(!s)return "";
  if(s.includes("maywood"))return "maywood";
  if(s.includes("26th")||s.includes("26 st")||s.includes("26 street")||s==="la 26")return "la26";
  if(s.includes("sacramento")||s==="sac")return "sacramento";
  if(s.includes("indiana"))return "indiana";
  if(s.includes("new york")||s==="ny")return "newyork";
  return "";
}
function opsHeaderMap(headers){
  const normalized=headers.map(h=>String(h||"").trim().toLowerCase().replace(/[_\-]+/g," ").replace(/\s+/g," "));
  const find=(terms)=>{
    for(const term of terms){
      const exact=normalized.findIndex(h=>h===term);
      if(exact>=0)return exact;
    }
    for(const term of terms){
      const partial=normalized.findIndex(h=>h.includes(term));
      if(partial>=0)return partial;
    }
    return -1;
  };
  return {normalized,find};
}
function opsNumber(value){
  if(value==null||value==="")return null;
  const n=Number(String(value).replace(/[$,%\s,]/g,""));
  return Number.isFinite(n)?n:null;
}
function opsCanonical(record){
  const copy={...record};
  delete copy.importedAt;
  delete copy._providedFields;
  return JSON.stringify(copy,Object.keys(copy).sort());
}
function opsCurrentFilter(){
  let saved={period:"YTD",date:new Date().toISOString().slice(0,10)};
  try{saved={...saved,...JSON.parse(localStorage.getItem(OPS_FILTER_KEY)||"{}")}}catch(e){}
  return saved;
}
function opsSaveFilter(period,date){
  const value={period,date};
  localStorage.setItem(OPS_FILTER_KEY,JSON.stringify(value));
  return value;
}
function opsRange(period,date){
  const end=new Date(`${date}T23:59:59`);
  if(period==="Daily"){
    const start=new Date(`${date}T00:00:00`);
    return {start,end};
  }
  if(period==="Weekly"){
    const start=new Date(`${date}T00:00:00`);
    const day=(start.getDay()+6)%7;
    start.setDate(start.getDate()-day);
    const finish=new Date(start);
    finish.setDate(finish.getDate()+6);
    finish.setHours(23,59,59,999);
    return {start,end:finish>end?end:finish};
  }
  const start=new Date(end.getFullYear(),0,1);
  return {start,end};
}
function opsRecordDate(record){
  return record.createdDate||record.completedDate||record.dueDate||"";
}
function opsRecordOccursInRange(record,range){
  return [record.createdDate,record.completedDate,record.dueDate]
    .filter(Boolean)
    .some(value=>opsInRange(value,range));
}
function opsInRange(dateValue,range){
  if(!dateValue)return false;
  const d=new Date(`${dateValue}T12:00:00`);
  return !isNaN(d)&&d>=range.start&&d<=range.end;
}
function opsIsCompleted(record){
  return /complete|closed|done|resolved/i.test(record.status||"");
}
function opsIsOpen(record){
  return !opsIsCompleted(record);
}
function opsIsOverdue(record,asOf){
  if(!record.dueDate||!opsIsOpen(record))return false;
  return new Date(`${record.dueDate}T23:59:59`)<asOf;
}
function opsType(record,kind){
  const type=String(record.type||"").toLowerCase();
  return kind==="reactive"?/reactive|corrective|breakdown|emergency/.test(type):/preventive|planned|pm\b/.test(type);
}
function legacySummaryFor(site){
  return typeof FIXED_YTD_DATA!=="undefined"?FIXED_YTD_DATA[site]||null:null;
}
async function storedSummaryFor(site){
  const stored=await opsGet(OPS_STORES.summaries,site);
  return stored?.data||null;
}
async function effectiveSummaryFor(site){
  return (await storedSummaryFor(site))||legacySummaryFor(site);
}
function importedSummaryFields(summary){
  if(!summary)return [];
  const fields=new Set(summary.importedFields||[]);
  const details=summary.reportDetails||{};
  if(details.wo_by_assignee){
    fields.add("assignees");
    fields.add("notAssigned");
  }
  if(details.history_by_assignee){
    fields.add("completedYTD");
    fields.add("laborHours");
  }
  if(details.on_time_overdue){
    fields.add("completedYTD");
    fields.add("onTimeCompleted");
    fields.add("overdueCompleted");
    fields.add("noDueDateCompleted");
  }
  if(details.asset_costs){
    fields.add("totalDowntime");
    fields.add("cost");
    fields.add("assetImpactRows");
  }
  if(details.work_order_requests){
    fields.add("pending");
  }
  return [...fields];
}
function mergeImportedSummaryIntoKpi(base,summary,site){
  if(!summary)return base;
  const fields=new Set(importedSummaryFields(summary));
  if(!fields.size)return base;

  const result={
    ...(base||{
      source:"records",site,total:0,created:0,completed:0,open:0,overdue:0,reactive:0,preventive:0,
      unassigned:0,pending:0,avgAge:null,cost:null,totalDowntime:null,
      plannedDowntime:null,unplannedDowntime:null,completedOnTime:null,
      completedOverdue:null,completedNoDue:null,laborHours:null,
      backlogRows:[],assetImpactRows:[]
    }),
    source:base?"mixed":"summary",
    site
  };

  const numberValue=value=>{
    if(value==null||value==="")return null;
    const parsed=opsNumber(value);
    return parsed==null?null:parsed;
  };

  const map=[
    ["workOrders","total"],
    ["createdYTD","created"],
    ["completedYTD","completed"],
    ["open","open"],
    ["overdue","overdue"],
    ["reactive","reactive"],
    ["preventive","preventive"],
    ["notAssigned","unassigned"],
    ["pending","pending"],
    ["avgAge","avgAge"],
    ["cost","cost"],
    ["totalDowntime","totalDowntime"],
    ["planned","plannedDowntime"],
    ["unplanned","unplannedDowntime"],
    ["onTimeCompleted","completedOnTime"],
    ["overdueCompleted","completedOverdue"],
    ["noDueDateCompleted","completedNoDue"],
    ["laborHours","laborHours"]
  ];

  const rowLevelAuthoritative=base?.source==="records";
  const rowLevelFields=new Set(["workOrders","createdYTD","completedYTD","open","reactive","preventive","notAssigned"]);

  map.forEach(([sourceKey,targetKey])=>{
    if(!fields.has(sourceKey))return;
    if(rowLevelAuthoritative&&rowLevelFields.has(sourceKey))return;
    result[targetKey]=numberValue(summary[sourceKey]);
  });

  if(fields.has("assignees")){
    result.backlogRows=summary.assignees||[];
  }
  if(fields.has("assetImpactRows")){
    result.assetImpactRows=summary.assetImpactRows||[];
  }

  return result;
}
function legacyToKpi(site,d){
  if(!d)return null;
  const numHours=v=>{const n=parseFloat(String(v??"").replace(/[^\d.-]/g,""));return Number.isFinite(n)?n:null};
  const cost=opsNumber(d.cost);
  return {
    source:"legacy",site,total:Number(d.workOrders)||0,created:d.createdYTD??d.workOrders??null,completed:d.completedYTD??null,
    open:d.open??null,overdue:Number(d.overdue)||0,reactive:Number(d.reactive)||0,preventive:Number(d.preventive)||0,
    unassigned:Number(d.notAssigned)||0,pending:d.pending??null,avgAge:Number(d.avgAge)||null,cost,
    totalDowntime:numHours(d.totalDowntime),plannedDowntime:numHours(d.planned),unplannedDowntime:numHours(d.unplanned),
    mttr:numHours(d.mttr),mtbf:numHours(d.mtbf),backlogRows:d.assignees||[],
    completedOnTime:d.onTimeCompleted??null,completedOverdue:d.overdueCompleted??null,
    completedNoDue:d.noDueDateCompleted??null,laborHours:numHours(d.laborHours),
    assetImpactRows:d.assetImpactRows||[]
  };
}
function combineKpis(parts){
  const valid=parts.filter(Boolean);
  if(!valid.length)return null;
  const sum=k=>valid.reduce((t,p)=>t+(Number(p[k])||0),0);
  const total=sum("total");
  const weightedAge=total?valid.reduce((t,p)=>t+(Number(p.avgAge)||0)*(Number(p.total)||0),0)/total:null;
  const nullableSum=k=>valid.every(p=>p[k]!=null)?valid.reduce((t,p)=>t+(Number(p[k])||0),0):null;
  return {
    source:valid.every(p=>p.source==="records")?"records":valid.every(p=>p.source==="legacy")?"legacy":"mixed",
    total,created:nullableSum("created"),completed:nullableSum("completed"),open:nullableSum("open"),overdue:sum("overdue"),
    reactive:sum("reactive"),preventive:sum("preventive"),unassigned:sum("unassigned"),pending:nullableSum("pending"),
    avgAge:weightedAge,cost:nullableSum("cost"),totalDowntime:nullableSum("totalDowntime"),
    plannedDowntime:nullableSum("plannedDowntime"),unplannedDowntime:nullableSum("unplannedDowntime"),
    mttr:null,mtbf:null,
    completedOnTime:nullableSum("completedOnTime"),completedOverdue:nullableSum("completedOverdue"),
    completedNoDue:nullableSum("completedNoDue"),laborHours:nullableSum("laborHours"),
    assetImpactRows:valid.flatMap(p=>p.assetImpactRows||[]),
    backlogRows:valid.flatMap(p=>p.backlogRows||[])
  };
}
function calculateRecordKpis(records,range,site){
  const locationRecords=records.filter(r=>site==="all"||r.location===site);
  const selected=locationRecords.filter(r=>opsRecordOccursInRange(r,range));
  if(!selected.length)return null;

  const asOf=range.end;
  const created=locationRecords.filter(r=>r.createdDate&&opsInRange(r.createdDate,range));
  const completed=locationRecords.filter(r=>{
    if(!opsIsCompleted(r))return false;
    if(r.completedDate)return opsInRange(r.completedDate,range);
    return r.createdDate&&opsInRange(r.createdDate,range);
  });
  const open=selected.filter(opsIsOpen);
  const overdue=open.filter(r=>opsIsOverdue(r,asOf));
  const reactive=selected.filter(r=>opsType(r,"reactive"));
  const preventive=selected.filter(r=>opsType(r,"preventive"));
  const unassigned=open.filter(r=>!String(r.assignee||"").trim());
  const pending=open.filter(r=>/request|pending|awaiting approval/i.test(r.status||""));

  const ages=selected.map(r=>{
    const start=r.createdDate?new Date(`${r.createdDate}T00:00:00`):null;
    const stop=r.completedDate?new Date(`${r.completedDate}T00:00:00`):asOf;
    return start&&!isNaN(start)&&stop>=start?(stop-start)/86400000:null;
  }).filter(Number.isFinite);

  const groups={};
  open.forEach(r=>{
    const name=String(r.assignee||"").trim()||"Not assigned";
    const g=groups[name]||(groups[name]={name,active:0,overdue:0,onTime:0,reactive:0,preventive:0});
    g.active++;
    if(opsIsOverdue(r,asOf))g.overdue++;else g.onTime++;
    if(opsType(r,"reactive"))g.reactive++;
    if(opsType(r,"preventive"))g.preventive++;
  });

  const downtime=selected.map(r=>r.downtimeHours).filter(Number.isFinite);
  const planned=selected.map(r=>r.plannedDowntimeHours).filter(Number.isFinite);
  const unplanned=selected.map(r=>r.unplannedDowntimeHours).filter(Number.isFinite);
  const costs=selected.map(r=>r.cost).filter(Number.isFinite);

  return {
    source:"records",
    site,
    total:selected.length,
    created:created.length,
    completed:completed.length,
    open:open.length,
    overdue:overdue.length,
    reactive:reactive.length,
    preventive:preventive.length,
    unassigned:unassigned.length,
    pending:pending.length,
    avgAge:ages.length?ages.reduce((a,b)=>a+b,0)/ages.length:null,
    cost:costs.length?costs.reduce((a,b)=>a+b,0):null,
    totalDowntime:downtime.length?downtime.reduce((a,b)=>a+b,0):null,
    plannedDowntime:planned.length?planned.reduce((a,b)=>a+b,0):null,
    unplannedDowntime:unplanned.length?unplanned.reduce((a,b)=>a+b,0):null,
    completedOnTime:null,
    completedOverdue:null,
    completedNoDue:null,
    laborHours:selected.map(r=>r.laborHours).filter(Number.isFinite).reduce((a,b)=>a+b,0)||null,
    assetImpactRows:[],
    backlogRows:Object.values(groups).sort((a,b)=>b.active-a.active),
    hasDueDates:selected.some(r=>!!r.dueDate)
  };
}
async function calculateKPIs(filters){
  const records=await opsGetAll(OPS_STORES.workOrders);
  const range=opsRange(filters.period,filters.date);
  const sites=currentSite==="all"?KPI_SITES:[currentSite];

  const parts=(await Promise.all(sites.map(async site=>{
    const rowKpi=calculateRecordKpis(records,range,site);

    if(filters.period!=="YTD"){
      const base=rowKpi||{
        source:"records",site,total:0,created:0,completed:0,open:0,overdue:0,
        reactive:0,preventive:0,unassigned:0,pending:0,avgAge:null,cost:null,
        totalDowntime:null,plannedDowntime:null,unplannedDowntime:null,
        completedOnTime:null,completedOverdue:null,completedNoDue:null,
        laborHours:null,assetImpactRows:[],backlogRows:[]
      };
      return applyMetricResetsToKpi(base,site);
    }

    const storedSummary=await storedSummaryFor(site);
    const legacyKpi=legacyToKpi(site,legacySummaryFor(site));

    if(rowKpi&&legacyKpi){
      if(!rowKpi.hasDueDates)rowKpi.overdue=legacyKpi.overdue;
      if(!storedSummary?.assignees&&legacyKpi.backlogRows?.length){
        rowKpi.backlogRows=legacyKpi.backlogRows;
      }
    }

    const base=rowKpi||legacyKpi;
    const merged=mergeImportedSummaryIntoKpi(base,storedSummary,site);
    return applyMetricResetsToKpi(merged,site);
  }))).filter(Boolean);

  return combineKpis(parts)||{
    source:"records",total:0,created:0,completed:0,open:0,overdue:0,
    reactive:0,preventive:0,unassigned:0,pending:0,avgAge:null,cost:null,
    totalDowntime:null,plannedDowntime:null,unplannedDowntime:null,
    completedOnTime:null,completedOverdue:null,completedNoDue:null,
    laborHours:null,assetImpactRows:[],backlogRows:[]
  };
}
async function calculateProduction(filters){
  // Always include the temporary live production baseline in calculations.
  // IndexedDB records with the same Location + Date + Shift override the baseline,
  // so future uploads/corrections still work without double-counting.
  const stored=await opsGetAll(OPS_STORES.production);
  const merged=new Map();
  for(const r of stored){
    const key=r.key||`${r.location}|${r.date}|${r.shift}`;
    merged.set(key,r);
  }
  // For the temporary live version, verified hard-coded records are authoritative
  // so stale/zero IndexedDB records cannot overwrite the live baseline.
  for(const r of HARDCODED_PRODUCTION_RECORDS){
    const key=`${r.location}|${r.date}|${r.shift}`;
    merged.set(key,{...r,key});
  }
  const records=[...merged.values()];
  const range=opsRange(filters.period,filters.date);
  const selected=records.filter(r=>(currentSite==="all"||r.location===currentSite)&&opsInRange(r.date,range));
  return {
    batches:selected.reduce((t,r)=>t+(Number(r.batches)||0),0),
    pallets:selected.reduce((t,r)=>t+(Number(r.pallets)||0),0)
  };
}
function renderBacklog(kpi){
  const body=document.getElementById("backlogRows");
  if(!body)return;
  let rows=kpi.backlogRows||[];
  if(kpi.source==="legacy"||kpi.source==="mixed"){
    rows=rows.map(r=>Array.isArray(r)?{name:r[0],active:r[1],overdue:r[2],onTime:r[3],reactive:r[4],preventive:r[5]}:r);
  }
  body.innerHTML=rows.length?rows.map(r=>`<tr><td>${escapeHTML(r.name||"—")}</td><td>${r.active??0}</td><td>${r.overdue??0}</td><td>${r.onTime??0}</td><td>${r.reactive??0}</td><td>${r.preventive??0}</td></tr>`).join(""):'<tr><td colspan="6" class="empty">No backlog detail available for this filter.</td></tr>';
}

function renderClickMaintReportDetails(summary){
  const wrap=document.getElementById("clickMaintDetail26");
  const target=document.getElementById("clickMaintReportTables");
  if(!wrap||!target)return;
  const details=summary?.reportDetails;
  const show=currentSite==="la26"&&details;
  wrap.hidden=!show;
  if(!show){target.innerHTML="";return}
  target.innerHTML=Object.values(details).map(report=>{
    const head=report.headers.map(h=>`<th>${escapeHTML(h)}</th>`).join("");
    const body=report.rows.map(row=>`<tr>${row.map(v=>`<td>${escapeHTML(v)}</td>`).join("")}</tr>`).join("");
    return `<div class="clickmaint-report"><h4>${escapeHTML(report.title)}</h4><div class="file-meta">${escapeHTML(report.filename)}</div><div class="table-scroll"><table><thead><tr>${head}</tr></thead><tbody>${body}</tbody></table></div></div>`;
  }).join("");
}

