window.saveProductionEntry=async function(){
  const location=document.getElementById("productionLocation").value;
  const date=document.getElementById("productionDate").value;
  const shift=document.getElementById("productionShift").value;
  const batches=opsNumber(document.getElementById("productionBatches").value);
  const pallets=opsNumber(document.getElementById("productionPallets").value);
  if(!location||!date||!shift||batches==null||pallets==null){opsText("productionUploadStatus","Complete Location, Date, Shift, Batches and Pallets.");return}
  const key=`${location}|${date}|${shift}`,old=await opsGet(OPS_STORES.production,key);
  const record={key,location,date,shift,batches,pallets,importedAt:new Date().toISOString()};
  await opsPut(OPS_STORES.production,record);
  const changed=!old?"added":opsCanonical(old)===opsCanonical(record)?"unchanged":"updated";
  const timestamp=new Date().toISOString();
  await opsAdd(OPS_STORES.history,{timestamp,filename:"Manual production entry",reportType:"Production",locations:[location],dateRange:[date,date],recordsDetected:1,added:changed==="added"?1:0,updated:changed==="updated"?1:0,unchanged:changed==="unchanged"?1:0,rejected:0});
  localStorage.setItem("lamonicasDataLastUpdated",timestamp);
  opsText("productionUploadStatus",`Production record ${changed}.`);
  await Promise.all([renderDashboard(),renderImportHistory(),renderProductionHistory()]);
};
