async function migrateLegacyProduction(){
  let legacy=[];try{legacy=JSON.parse(localStorage.getItem("lamonicasProductionRecords")||"[]")}catch(e){}
  for(const r of legacy){
    const location=opsLocation(r.location)||r.location;
    const date=opsDateString(r.date),shift=String(r.shift||"").replace(/^Shift\s*/i,"");
    if(!location||!date||!shift)continue;
    const key=`${location}|${date}|${shift}`;
    const existing=await opsGet(OPS_STORES.production,key);
    if(existing)continue;
    await opsPut(OPS_STORES.production,{key,location,date,shift,batches:Number(r.batches)||0,pallets:Number(r.pallets)||0,importedAt:r.updatedAt||new Date().toISOString()});
  }
  await seedHardcodedProduction();
}

