function setupOpsImportUI(){
  Object.entries(OPS_IMPORT_AREAS).forEach(([area,config])=>{
    const drop=document.getElementById(config.dropId);
    const input=document.getElementById(config.inputId);
    const upload=document.getElementById(config.analyzeFileId);
    const textSubmit=document.getElementById(config.analyzeTextId);

    if(drop&&input&&upload&&drop.dataset.opsBound!=="1"){
      drop.dataset.opsBound="1";

      const chooseFile=()=>input.click();

      drop.addEventListener("click",chooseFile);
      drop.addEventListener("keydown",event=>{
        if(event.key==="Enter"||event.key===" "){
          event.preventDefault();
          chooseFile();
        }
      });

      input.addEventListener("change",()=>{
        const file=input.files&&input.files[0];
        if(file)stageOpsFile(area,file);
      });

      ["dragenter","dragover"].forEach(type=>{
        drop.addEventListener(type,event=>{
          event.preventDefault();
          event.stopPropagation();
          drop.classList.add("dragging-over");
          if(event.dataTransfer)event.dataTransfer.dropEffect="copy";
        });
      });

      ["dragleave","dragend"].forEach(type=>{
        drop.addEventListener(type,event=>{
          event.preventDefault();
          event.stopPropagation();
          drop.classList.remove("dragging-over");
        });
      });

      drop.addEventListener("drop",event=>{
        event.preventDefault();
        event.stopPropagation();
        drop.classList.remove("dragging-over");
        const file=event.dataTransfer&&event.dataTransfer.files&&event.dataTransfer.files[0];
        if(file)stageOpsFile(area,file);
      });

      upload.addEventListener("click",event=>{
        event.preventDefault();
        analyzeOpsImport(area,"file");
      });
    }

    if(textSubmit&&textSubmit.dataset.opsBound!=="1"){
      textSubmit.dataset.opsBound="1";
      textSubmit.addEventListener("click",event=>{
        event.preventDefault();
        analyzeOpsImport(area,"text");
      });
    }
  });

  document.querySelectorAll("[data-choose-file]").forEach(button=>{
    if(button.dataset.opsBound==="1")return;
    button.dataset.opsBound="1";
    button.addEventListener("click",event=>{
      event.preventDefault();
      event.stopPropagation();
      const area=button.dataset.chooseFile;
      const config=opsImportArea(area);
      const input=document.getElementById(config.inputId);
      if(input)input.click();
    });
  });

  const cancel=document.getElementById("cancelImportBtn");
  if(cancel&&cancel.dataset.opsBound!=="1"){
    cancel.dataset.opsBound="1";
    cancel.addEventListener("click",cancelOpsImport);
  }

  const confirm=document.getElementById("confirmImportBtn");
  if(confirm&&confirm.dataset.opsBound!=="1"){
    confirm.dataset.opsBound="1";
    confirm.addEventListener("click",commitOpsImport);
  }

  const undo=document.getElementById("undoLastActionBtn");
  if(undo&&undo.dataset.opsBound!=="1"){
    undo.dataset.opsBound="1";
    undo.addEventListener("click",undoLastOpsAction);
  }

}
