/* Source block: clickmaint-copypaste-text-fix-v1 */
(function(){
"use strict";

const originalAnalyzeOpsImport=analyzeOpsImport;

function cleanClickMaintCopyText(raw){
  return String(raw||"")
    .replace(/\*\*/g,"")
    .replace(/\[([^\]]+)\]\([^)]+\)/g,"$1")
    .replace(/\\-/g,"-")
    .replace(/\u00a0/g," ")
    .replace(/\r/g,"")
    .split("\n")
    .map(line=>line.trim())
    .filter(Boolean)
    .join("\n");
}

function clickMaintHours(value){
  const text=String(value||"").trim().toLowerCase().replace(/,/g,"");
  if(!text)return null;

  if(/^-?\d+(?:\.\d+)?h$/.test(text)){
    return Number.parseFloat(text);
  }

  const match=text.match(
    /^(?:(\d+(?:\.\d+)?)h)?\s*(?:(\d+(?:\.\d+)?)m)?\s*(?:(\d+(?:\.\d+)?)s)?$/
  );
  if(!match||!match[0]||(!match[1]&&!match[2]&&!match[3]))return null;

  return (Number(match[1]||0))+
    (Number(match[2]||0)/60)+
    (Number(match[3]||0)/3600);
}

function clickMaintMoney(value){
  const match=String(value||"").replace(/,/g,"").match(/\$?\s*(-?\d+(?:\.\d+)?)/);
  return match?Number(match[1]):null;
}

function metricNearLabel(text,labelPattern,valuePattern,converter){
  const lines=text.split("\n");

  for(let i=0;i<lines.length;i++){
    if(!labelPattern.test(lines[i]))continue;

    for(const offset of [-1,1,-2,2]){
      const candidate=lines[i+offset];
      if(candidate==null||!valuePattern.test(candidate))continue;
      const value=converter(candidate);
      if(value!=null)return value;
    }

    const sameLine=lines[i].match(valuePattern);
    if(sameLine){
      const value=converter(sameLine[0]);
      if(value!=null)return value;
    }
  }

  return null;
}

function inferClickMaintSite(text){
  const lower=text.toLowerCase();

  if(/\(ny\)|\bnew york\b|\bny\b/.test(lower))return "newyork";
  if(/\b26th\b|\b26th street\b|\bla 26\b/.test(lower))return "la26";
  if(/\bmaywood\b/.test(lower))return "maywood";
  if(/\bindiana\b/.test(lower))return "indiana";
  if(/\bsacramento\b/.test(lower))return "sacramento";

  return currentSite!=="all"?currentSite:"";
}

function parseClickMaintAssetRows(text){
  const lines=text.split("\n");
  const rows=[];

  function isAssetStart(index){
    const name=lines[index];
    const id=lines[index+1];
    if(!name||!id)return false;
    if(!/^\d+$/.test(id))return false;
    if(/^(name|id|status|online|offline|filters|asset costs)/i.test(name))return false;
    return true;
  }

  for(let i=0;i<lines.length;i++){
    if(!isAssetStart(i))continue;

    const name=lines[i];
    const id=lines[i+1];
    let end=lines.length;

    for(let j=i+2;j<Math.min(lines.length,i+30);j++){
      if(isAssetStart(j)){
        end=j;
        break;
      }
    }

    const block=lines.slice(i+2,end);
    let downtime=0;
    let foundDowntime=false;
    let cost=0;
    let foundCost=false;
    let area="";

    for(const line of block){
      if(/\b\d+\s*(?:mo|month|months|d|day|days)\b/i.test(line))continue;

      const hours=clickMaintHours(line);
      if(hours!=null&&hours>=0){
        downtime=Math.max(downtime,hours);
        foundDowntime=true;
      }

      if(/^\$[\d,]+(?:\.\d+)?$/.test(line)){
        const money=clickMaintMoney(line);
        if(money!=null){
          cost=Math.max(cost,money);
          foundCost=true;
        }
      }

      if(/^(NY|New York|26th Street|Maywood|Indiana|Sacramento)$/i.test(line)){
        area=line;
      }
    }

    if(!area){
      const suffix=name.match(/\((NY|New York|Maywood|Indiana|Sacramento)\)\s*$/i);
      if(suffix)area=suffix[1];
    }

    rows.push({
      id,
      name,
      downtime:foundDowntime?downtime:0,
      cost:foundCost?cost:0,
      area
    });

    i=end-1;
  }

  return rows;
}

function parseClickMaintCopiedAssetReport(raw){
  const text=cleanClickMaintCopyText(raw);

  const looksLikeAssetReport=
    /asset costs?\s*&\s*downtime/i.test(text) ||
    (
      /total downtime/i.test(text) &&
      /maintenance cost/i.test(text) &&
      /\bonline\s*%/i.test(text)
    );

  if(!looksLikeAssetReport)return null;

  const hourValue=/\b[\d,]+(?:\.\d+)?h\b|\b\d+h\s+\d+m\b|\b\d+m\s+\d+s\b/i;
  const moneyValue=/\$[\d,]+(?:\.\d+)?/;

  const totalCost=metricNearLabel(
    text,/^total cost$/i,moneyValue,clickMaintMoney
  );
  const totalDowntime=metricNearLabel(
    text,/^total downtime$/i,hourValue,clickMaintHours
  );
  const plannedDowntime=metricNearLabel(
    text,/^planned downtime$/i,hourValue,clickMaintHours
  );
  const unplannedDowntime=metricNearLabel(
    text,/^unplanned downtime$/i,hourValue,clickMaintHours
  );
  const mttr=metricNearLabel(
    text,/^mttr$/i,hourValue,clickMaintHours
  );
  const mtbf=metricNearLabel(
    text,/^mtbf$/i,hourValue,clickMaintHours
  );

  const allAssets=parseClickMaintAssetRows(text);
  const impactedAssets=allAssets.filter(
    row=>Number(row.downtime)>0||Number(row.cost)>0
  );

  if(
    totalCost==null &&
    totalDowntime==null &&
    plannedDowntime==null &&
    unplannedDowntime==null &&
    !allAssets.length
  ){
    return null;
  }

  return {
    site:inferClickMaintSite(text),
    reportType:"ClickMaint — Asset Cost / Downtime",
    detailKey:"asset_costs",
    cleanedText:text,
    assets:allAssets,
    patch:{
      ...(totalCost==null?{}:{cost:totalCost}),
      ...(totalDowntime==null?{}:{totalDowntime}),
      ...(plannedDowntime==null?{}:{plannedDowntime}),
      ...(unplannedDowntime==null?{}:{unplannedDowntime}),
      ...(mttr==null?{}:{mttr}),
      ...(mtbf==null?{}:{mtbf}),
      assetImpactRows:impactedAssets
    }
  };
}

async function previewCopiedClickMaintReport(area,rawText){
  const parsed=parseClickMaintCopiedAssetReport(rawText);
  if(!parsed)return false;

  let site=parsed.site;
  if(!site&&currentSite!=="all")site=currentSite;

  if(!site){
    throw new Error(
      "ClickMaint downtime data was recognized, but the location could not be identified. " +
      "Select a location at the top or include a location such as NY, Maywood, or 26th Street."
    );
  }

  await ensureOpsDbReady();

  const stored=await opsGet(OPS_STORES.summaries,site);
  const current=stored?.data||legacySummaryFor(site)||{};
  const reportDetails={...(current.reportDetails||{})};

  reportDetails.asset_costs={
    title:"Asset Cost / Downtime",
    filename:"Pasted ClickMaint text",
    headers:["Asset","ID","Downtime","Maintenance Cost","Location"],
    rows:parsed.assets.map(row=>[
      row.name,
      row.id,
      row.downtime,
      row.cost,
      row.area
    ])
  };

  const importedFields=[
    ...new Set([
      ...(current.importedFields||[]),
      ...Object.keys(parsed.patch)
    ])
  ];

  const next={
    ...current,
    ...parsed.patch,
    reportDetails,
    importedFields,
    baselineUpdated:new Date().toISOString().slice(0,10)
  };

  const changed=opsCanonical(current)!==opsCanonical(next);

  activeImportArea=area;
  pendingOpsImport={
    mode:"summary",
    area,
    sourceKind:"text",
    sourceName:"Pasted ClickMaint text",
    reportType:parsed.reportType,
    summarySite:site,
    summaryData:next,
    recordsDetected:parsed.assets.length,
    records:[],
    rejected:[],
    added:0,
    updated:changed?1:0,
    unchanged:changed?0:1,
    locations:[site],
    dateRange:["",""]
  };

  renderImportPreview();
  opsSetAreaStatus(area,"Preview ready");
  return true;
}

analyzeOpsImport=async function(area,sourceKind="file"){
  if(sourceKind!=="text"){
    return originalAnalyzeOpsImport(area,sourceKind);
  }

  const config=opsImportArea(area);
  const rawText=document.getElementById(config.textId)?.value||"";

  if(!rawText.trim()){
    return originalAnalyzeOpsImport(area,sourceKind);
  }

  const parsed=parseClickMaintCopiedAssetReport(rawText);
  if(!parsed){
    return originalAnalyzeOpsImport(area,sourceKind);
  }

  const button=document.getElementById(config.analyzeTextId);
  const originalText=button?.textContent||"Submit Text Data";

  if(button){
    button.disabled=true;
    button.textContent="Processing Text...";
  }

  opsSetAreaStatus(area,"Processing text");
  opsText("importStageStatus","Reading ClickMaint text...");

  try{
    await previewCopiedClickMaintReport(area,rawText);
  }catch(error){
    activeImportArea=area;
    pendingOpsImport=null;

    const preview=document.getElementById("importPreview");
    if(preview){
      preview.hidden=false;
      opsText("importPreviewType","Downtime / Maintenance Detail");
      opsText("importPreviewSource","Pasted ClickMaint text");
      document.getElementById("importPreviewStats").innerHTML="";
      document.getElementById("importPreviewDetails").innerHTML=
        `<div class="result-bad">${escapeHTML(error.message)}</div>`;
      document.getElementById("importRejectedDetails").innerHTML="";
      document.getElementById("confirmImportBtn").disabled=true;
    }

    opsText("importStageStatus","Needs correction");
    opsSetAreaStatus(area,"Needs attention");
  }finally{
    if(button){
      button.disabled=false;
      button.textContent=originalText;
    }
  }
};

window.parseClickMaintCopiedAssetReport=parseClickMaintCopiedAssetReport;
})();

