async function seedPersistentSiteSummary(site,update,fields,batch){
  if(typeof ensureOpsDbReady!=="function"||typeof opsGet!=="function"||
     typeof opsPut!=="function"||typeof OPS_STORES==="undefined")return;

  await ensureOpsDbReady();
  const stored=await opsGet(OPS_STORES.summaries,site);
  const current=stored?.data||{};

  if(current.seedBatch===batch)return;

  const importedFields=[...new Set([
    ...(current.importedFields||[]),
    ...fields
  ])];

  const next={
    ...current,
    ...update,
    reportDetails:mergeReportDetails(current,update),
    importedFields,
    seedBatch:batch
  };

  await opsPut(OPS_STORES.summaries,{
    site,
    data:next,
    updatedAt:new Date().toISOString()
  });
}

function seedShiftNotes(){
  if(typeof SHIFT_NOTES_KEY==="undefined")return;

  let notes=[];
  try{ notes=JSON.parse(localStorage.getItem(SHIFT_NOTES_KEY)||"[]"); }
  catch(error){ notes=[]; }

  const existingIds=new Set(notes.map(note=>Number(note.id)));
  let changed=false;

  for(const note of SEEDED_SHIFT_NOTES){
    if(existingIds.has(Number(note.id)))continue;
    notes.push(note);
    existingIds.add(Number(note.id));
    changed=true;
  }

  if(changed){
    notes.sort((a,b)=>new Date(b.date)-new Date(a.date));
    localStorage.setItem(SHIFT_NOTES_KEY,JSON.stringify(notes));
  }
}

